const rows = $('Load Queued Videos').all().map(i => i.json || {});
const products = $('Load Products For Packshot').all().map(i => i.json || {});
const queuedRows = rows.filter(r => r.approval_status === 'approved' && r.render_status === 'queued');
const target = queuedRows[queuedRows.length - 1] || rows[rows.length - 1];
if (!target || !target.video_key) return [];

const TOKEN = $env.HF_TOKEN || '';
const matchedProd = products.find(p => p.product_key === target.product_key) || {};
const dePackshotUrl = String(matchedProd.packshot_image_url || '');
const rawRefVideo = String(target.final_video_url || '');
const isCleanerVideoOnNonCleaner = rawRefVideo.includes('7608202200036199702') && target.product_key !== 'prod_7in1_tech_cleaner';
const refVideoUrl = isCleanerVideoOnNonCleaner ? '' : rawRefVideo;

let scenes = [];
try {
  scenes = JSON.parse(target.scenes_json || '[]');
} catch (e) {
  scenes = [];
}

function findUrl(obj, depth = 0) {
  if (!obj || depth > 5) return '';
  if (typeof obj === 'string') {
    return /^https:\/\//.test(obj) && /\.(mp4|png|jpe?g|webp)(\?|$)/i.test(obj) ? obj : '';
  }
  if (Array.isArray(obj)) {
    for (const v of obj) {
      const u = findUrl(v, depth + 1);
      if (u) return u;
    }
    return '';
  }
  if (typeof obj === 'object') {
    for (const k of ['video', 'images', 'image', 'url', 'output', 'video_url', 'image_url']) {
      if (obj[k] !== undefined) {
        const u = findUrl(obj[k], depth + 1);
        if (u) return u;
      }
    }
  }
  return '';
}

// Download the German TikTok Shop original product image once and convert to base64 Data-URI
let packshotDataUrl = '';
if (dePackshotUrl) {
  try {
    const imgBuf = await this.helpers.httpRequest({
      method: 'GET',
      url: dePackshotUrl,
      headers: { 'User-Agent': 'Mozilla/5.0' },
      encoding: 'arraybuffer',
      timeout: 15000
    });
    const mime = dePackshotUrl.includes('.png') ? 'image/png' : (dePackshotUrl.includes('.webp') ? 'image/webp' : 'image/jpeg');
    packshotDataUrl = 'data:' + mime + ';base64,' + Buffer.from(imgBuf).toString('base64');
  } catch (e) {}
}

const firstTs = (scenes[0] && scenes[0].ref_timestamp) || '00:00:05.0';

// Process all 8 scenes IN PARALLEL (Promise.all) with portrait_16_9 (9:16 vertical) output!
const enrichedScenes = await Promise.all(scenes.map(async (s) => {
  const ts = s.ref_timestamp || firstTs;
  let frameDataUrl = '';
  if (refVideoUrl) {
    try {
      const thumbResp = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://ffmpeg.mafrapi.eu/api/ffmpeg/extract-thumbnail',
        headers: { 'Content-Type': 'application/json', 'User-Agent': 'Mozilla/5.0' },
        body: JSON.stringify({ videoUrl: refVideoUrl, timestamp: ts }),
        encoding: 'arraybuffer',
        timeout: 15000
      });
      frameDataUrl = 'data:image/jpeg;base64,' + Buffer.from(thumbResp).toString('base64');
    } catch (e) {}
  }

  let editedImageUrl = (s.generated_image_url && s.generated_image_url.includes('fal.media')) ? s.generated_image_url : '';

  if (TOKEN && !editedImageUrl) {
    const primaryImg = frameDataUrl || packshotDataUrl;
    const imgList = (frameDataUrl && packshotDataUrl) ? [frameDataUrl, packshotDataUrl] : (primaryImg ? [primaryImg] : []);
    if (primaryImg) {
      try {
        const i2iResp = await this.helpers.httpRequest({
          method: 'POST',
          url: 'https://router.huggingface.co/fal-ai/fal-ai/flux-2/edit',
          headers: {
            Authorization: 'Bearer ' + TOKEN,
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            prompt: s.edit_prompt || ('Vertical 9:16 smartphone POV product demonstration of ' + (matchedProd.product_name || target.product_key) + ', keeping the exact product from the reference image, photorealistic, no text overlays.'),
            image_url: primaryImg,
            image_urls: imgList,
            image_size: 'portrait_16_9'
          }),
          timeout: 45000
        });
        editedImageUrl = findUrl(i2iResp);
      } catch (e) {}
    }

    if (!editedImageUrl) {
      try {
        const t2iResp = await this.helpers.httpRequest({
          method: 'POST',
          url: 'https://router.huggingface.co/fal-ai/fal-ai/flux/schnell',
          headers: {
            Authorization: 'Bearer ' + TOKEN,
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            prompt: s.edit_prompt || ('Vertical 9:16 smartphone POV product demonstration of ' + (matchedProd.product_name || target.product_key) + ', photorealistic, no text overlays.'),
            image_size: 'portrait_16_9',
            num_inference_steps: 4
          }),
          timeout: 30000
        });
        editedImageUrl = findUrl(t2iResp);
      } catch (e) {}
    }
  }

  return {
    ...s,
    generated_image_url: editedImageUrl || dePackshotUrl,
    generated_clip_url: s.generated_clip_url || ''
  };
}));

if (TOKEN && enrichedScenes[0] && enrichedScenes[0].generated_image_url && !enrichedScenes[0].generated_clip_url) {
  try {
    const i2vResp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://router.huggingface.co/fal-ai/fal-ai/wan-i2v',
      headers: {
        Authorization: 'Bearer ' + TOKEN,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        prompt: enrichedScenes[0].motion_prompt || 'smooth realistic smartphone POV product demonstration',
        image_url: enrichedScenes[0].generated_image_url
      }),
      timeout: 55000
    });
    const clipUrl = findUrl(i2vResp);
    if (clipUrl) enrichedScenes[0].generated_clip_url = clipUrl;
  } catch (e) {}
}

return [{
  json: {
    ...target,
    scenes_json: JSON.stringify(enrichedScenes),
    render_status: 'ready_for_ffmpeg'
  }
}];
